using System.Buffers.Binary;
using System.Security.Cryptography;
using Spyro.Editor.Core.Exporting;

internal static class NativeGreenWizardPropertiesCandidateCases
{
    public static void Run(string imagePath)
    {
        // These goldens were independently calculated from untouched native
        // rows/properties/fixups, not generated by this candidate compiler.
        NativeGreenWizardCandidateSource source = NativeGreenWizardCandidateSource.Inspect(imagePath);
        NativeGreenWizardPropertiesCandidatePlan t17 = Compile("wizardpeak", 17);
        Verify(t17, "1b5d51f0d999d19baa6f9c5ca17da62e17dba8ad6fbf39b8fb2d3d4a2a72406f",
            "719b346c3d6e31495432d9da3a84ce58edcfee714509ac007f8c6ba42db29d01", 0xBF);
        Require(t17.Targets.Single().OwnedExtentByteLength == 0xD4 &&
                t17.Targets.Single().OutputRowSha256 == "8c98cfc44966320d597570ea33c360efbb36a41e62ee3696a7984a776bbaabda" &&
                t17.Targets.Single().OutputPropertiesSha256 == "99cd42906158a7bb1a95570982677f8e847247e6a7878dcb7b9a8d45469459f5",
            "The decoded T17 owner or independently pinned row/properties golden changed.");
        Require(t17.Targets.Single().RoutePoints.SequenceEqual(new[]
            { new WizardPeakGreenWizardRoutePoint(123566, 87020, 16656), new WizardPeakGreenWizardRoutePoint(117043, 83876, 16656) }),
            "T17 donor-relative route coordinates were not translated exactly.");

        NativeGreenWizardPropertiesCandidatePlan t24 = Compile("wizardpeak", 24);
        Verify(t24, "7a7fa254e8b67c8775cbaa3434707c6e5624ab81cc97ebb931d4fd56a1d560b2",
            "24a9a1e0d22e8b10b480ad1f71fd3b92c234533e43daf0b1d4d238430ea87e5f", 0xBF);
        Require(t24.Targets.Single().OutputRowSha256 == "4316b75d1f06c73b8a49b545fcfe838dcf91e1b9a38a8cd16936c4371a6a2177" &&
                t24.Targets.Single().OutputPropertiesSha256 == "52f747a5aa5c2c4beff2813aa8722c876d881dff77a564b669ffb24d8fef732f" &&
                Hash(t24.CopyOutputScene().AsSpan(0xCAC0, 0x74)) == "0aef88ee09413e5ef08f685049698cca6b3e07846d1bafaf34cbf8627936ad73",
            "The new separate candidate changed one of the four existing T24 native goldens.");

        NativeGreenWizardPropertiesCandidatePlan batch = Compile("wizardpeak", 24, 17);
        Verify(batch, "de85a4700b253417f1a4efc60004b8a8664cd7a9612d3372484d57a9f252cb39",
            "a590839cafcafdb39c9fdd6fbf1cee2e82570355c9b474ac77caec6b849eaf0c", 0xBF);
        Require(batch.PlanSha256 == Compile("wizardpeak", 17, 24).PlanSha256 &&
                batch.Targets.Select(target => target.PropertiesOffset).Distinct().Count() == 2 &&
                batch.Targets.Select(target => target.TrueIndex).SequenceEqual(new[] { 17, 24 }),
            "Request ordering changed the candidate or two mutable instances shared their storage.");

        NativeGreenWizardPropertiesCandidatePlan cross = Compile("magiccrafters", 27);
        Verify(cross, "68f283f14267dabdb22432cadcdd7108f9b0f350d75fba910ec1c5658bde7d19",
            "48893f21d2748a3d2b77143240538936958d446a74605b119f0dca4041f42ba3", 0xBD);
        Require(cross.Donor.LevelKey == "wizardpeak" && cross.Target.LevelKey == "magiccrafters" &&
                cross.DependencyRequest.Instances.Single().DonorScene?.SourceSha256 == cross.Donor.SceneSha256 &&
                cross.Donor.SceneSha256 != cross.Target.SceneSha256 &&
                cross.Targets.Single().OutputPropertiesSha256 == "bfdffde6c8d48121ba21df0ca76be49451f8bab49acdd6c586f153454ec2d47a" &&
                cross.Targets.Single().OutputRowSha256 == "284d7bede83feef75ab4ea53dd3938e35dcdd63e2b0a2574d5a34aab3453de2a",
            "The cross-level candidate did not carry independent donor evidence/native target row policy.");
        Require(cross.Targets.Single().RoutePoints.SequenceEqual(new[]
            { new WizardPeakGreenWizardRoutePoint(88832, 41851, 23737), new WizardPeakGreenWizardRoutePoint(82309, 38707, 23737) }),
            "The cross-level candidate silently reused native target routes instead of imported donor routes.");

        Reject(() => Compile("wizardpeak", 10), "retired");
        Reject(() => Compile("wizardpeak", 25), "extent");
        Reject(() => Compile("wizardpeak", 17, 17), "duplicate");
        Reject(() => Compile("wizardpeak"), "target");
        Reject(() => Compile("wizardpeak", -1), "index");
        Reject(() => Compile("wizardpeak", 165), "index");
        Reject(() => Compile("wizardpeak", int.MaxValue), "index");
        Reject(() => Compile("wizardpeak", 6), "owner");
        Reject(() => Compile("magiccrafters", 26), "owner");
        Reject(() => Compile("missing", 17), "level");
        Reject(() => NativeGreenWizardPropertiesCandidateCompiler.Compile(source,
            new("wizardpeak", 28, "wizardpeak", [17])), "donor");
        Reject(() => NativeGreenWizardPropertiesCandidateCompiler.Compile(source,
            new("missing", 6, "wizardpeak", [17])), "level");
        byte[] detached = source.GetLevel("wizardpeak").CopyScene(); detached[^1] ^= 1;
        byte[] outputCopy = t17.CopyOutputScene(); outputCopy[0] ^= 1;
        Require(Hash(source.GetLevel("wizardpeak").CopyScene()) == t17.Donor.SceneSha256 &&
                t17.OutputSceneSha256 == Hash(t17.CopyOutputScene()) &&
                t17.PlanSha256 == Compile("wizardpeak", 17).PlanSha256,
            "A caller mutated the immutable source certificate or frozen candidate output.");
        Console.WriteLine("NATIVE_GREEN_WIZARD_PROPERTIES_CANDIDATE_SMOKE_OK T17 + T24 private batch + true cross-level T6-to-T27; independent goldens/complement/inverse; 12 rejected requests; candidate-only, no BIN/CUE");

        NativeGreenWizardPropertiesCandidatePlan Compile(string target, params int[] indices) =>
            NativeGreenWizardPropertiesCandidateCompiler.Compile(source, new("wizardpeak", 6, target, indices));
    }

    private static void Verify(NativeGreenWizardPropertiesCandidatePlan plan, string sceneHash, string fixupHash, int fixupCount)
    {
        Require(plan.CandidateOnly && !plan.RuntimeVerified && !plan.NormalCreateBinReady &&
                plan.SourceImageSha256 == NativeGreenWizardCandidateSource.OriginalImageSha256 &&
                plan.OutputSceneSha256 == sceneHash && plan.PlanSha256.Length == 64,
            "Candidate authority/source/output identity changed or inherited an old runtime proof.");
        byte[] before = plan.CopySourceScene(), after = plan.CopyOutputScene(), applied = before.ToArray();
        Require(Hash(before) == plan.Target.SceneSha256 && before.Length == after.Length &&
                plan.Writes.Count == plan.Targets.Count * 2 + 1, "Candidate altered fixed native owner geometry.");
        bool[] touched = new bool[before.Length];
        foreach (NativeGreenWizardCandidateWrite write in plan.Writes)
        {
            int offset = checked((int)write.Address.Final.Offset);
            byte[] oldBytes = Convert.FromHexString(write.BeforeHex), newBytes = Convert.FromHexString(write.AfterHex);
            Require(write.Address.Original.Offset == offset && write.Address.Final.ByteLength == newBytes.Length &&
                    write.Address.Original.ByteLength == oldBytes.Length && newBytes.Length == oldBytes.Length &&
                    applied.AsSpan(offset, oldBytes.Length).SequenceEqual(oldBytes), "Typed candidate write preimage/domain/length mismatch.");
            for (int i = offset; i < offset + newBytes.Length; i++)
            { Require(!touched[i], "Candidate writes overlap."); touched[i] = true; }
            newBytes.CopyTo(applied, offset);
        }
        Require(applied.AsSpan().SequenceEqual(after), "Typed writes do not reconstruct the exact complete output scene.");
        for (int i = 0; i < before.Length; i++)
            if (!touched[i]) Require(before[i] == after[i], $"Protected byte 0x{i:X} changed.");
        foreach (NativeGreenWizardCandidateTarget target in plan.Targets)
        {
            int row = target.PointerFieldSceneOffset, properties = target.PropertiesOffset;
            Require(BinaryPrimitives.ReadUInt32LittleEndian(after.AsSpan(row)) == properties &&
                    BinaryPrimitives.ReadUInt32LittleEndian(after.AsSpan(properties)) == properties + 0x28 &&
                    BinaryPrimitives.ReadUInt16LittleEndian(after.AsSpan(row + 0x36)) == 0x011B &&
                    before.AsSpan(properties + 0x50, target.OwnedExtentByteLength - 0x50).SequenceEqual(
                        after.AsSpan(properties + 0x50, target.OwnedExtentByteLength - 0x50)), "Private owner/tail/internal pointer mismatch.");
            foreach ((int start, int length) in new[] { (0x0C, 12), (0x20, 18), (0x43, 1), (0x46, 1), (0x4A, 1), (0x53, 1) })
                Require(before.AsSpan(row + start, length).SequenceEqual(after.AsSpan(row + start, length)),
                    "Native position/yaw/pod/culling/reward preservation failed.");
        }
        NativeGreenWizardCandidateWrite fixup = plan.Writes.Single(write => write.Kind == NativeGreenWizardCandidateWriteKind.PointerFixups);
        Require(Hash(Convert.FromHexString(fixup.AfterHex)) == fixupHash &&
                BinaryPrimitives.ReadUInt32LittleEndian(after.AsSpan(plan.Target.FixupOffset)) == fixupCount,
            "Exact native pointer fixup list changed unexpectedly.");
        foreach (NativeGreenWizardCandidateWrite write in plan.Writes)
            Convert.FromHexString(write.BeforeHex).CopyTo(applied, checked((int)write.Address.Original.Offset));
        Require(applied.AsSpan().SequenceEqual(before), "Candidate inverse did not restore every source scene byte.");
    }
    private static void Reject(Action run, string reason)
    {
        try { run(); } catch (InvalidDataException error) when (error.Message.Contains(reason, StringComparison.OrdinalIgnoreCase)) { return; }
        throw new InvalidOperationException($"Expected native Wizard candidate rejection containing '{reason}'.");
    }
    private static string Hash(ReadOnlySpan<byte> bytes) => Convert.ToHexStringLower(SHA256.HashData(bytes));
    private static void Require(bool value, string message) { if (!value) throw new InvalidOperationException(message); }
}
